$resolvedDestination = [IO.Path]::GetFullPath($DestinationPath)
$destinationRoot = [IO.Path]::GetPathRoot($resolvedDestination)
if ($resolvedDestination.TrimEnd('\', '/') -eq $destinationRoot.TrimEnd('\', '/')) {
    throw "Refusing to restore over a filesystem root: $resolvedDestination"
}

if (Test-Path -LiteralPath $resolvedDestination) {
    if (-not $Force) {
        throw "Destination already exists: $resolvedDestination. Re-run with -Force to replace it."
    }

    Remove-Item -LiteralPath $resolvedDestination -Recurse -Force
}

New-Item -ItemType Directory -Force -Path $resolvedDestination | Out-Null
$tempZip = Join-Path ([IO.Path]::GetTempPath()) ("cdt-workflow-restore-" + [Guid]::NewGuid().ToString('N') + '.zip')
try {
    [IO.File]::WriteAllBytes($tempZip, [Convert]::FromBase64String(($Base64Zip -replace '\s', '')))
    $actualSha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $tempZip).Hash.ToLowerInvariant()
    if ($actualSha256 -ne $ExpectedSha256) {
        throw "Checksum mismatch. Expected $ExpectedSha256 but got $actualSha256."
    }

    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [IO.Compression.ZipFile]::ExtractToDirectory($tempZip, $resolvedDestination)

    $actualFileCount = (Get-ChildItem -LiteralPath $resolvedDestination -Recurse -File | Measure-Object).Count
    if ($actualFileCount -ne $ExpectedFileCount) {
        throw "File count mismatch. Expected $ExpectedFileCount but restored $actualFileCount files."
    }

    Write-Host "Restored $actualFileCount files to $resolvedDestination"
    Write-Host "SHA-256 verified: $ExpectedSha256"
    Write-Host "Source commit: $SourceCommit"
    Write-Host "Bundle generated at: $GeneratedAt"
}
finally {
    if (Test-Path -LiteralPath $tempZip) {
        Remove-Item -LiteralPath $tempZip -Force
    }
}